create table if not exists public.ils_professional_assignment_mutation_alert_decision_log (id uuid primary key default gen_random_uuid(), failure_code text not null, window_minutes integer not null, observed_count bigint not null, review_threshold integer not null, stop_threshold integer not null, decision text not null check (decision in ('NORMAL','REVIEW','STOP')), threshold_type text not null, evaluated_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_alert_decision_log enable row level security; alter table public.ils_professional_assignment_mutation_alert_decision_log force row level security; revoke all on public.ils_professional_assignment_mutation_alert_decision_log from anon,authenticated; create index if not exists ils_mutation_alert_decision_log_time_idx on public.ils_professional_assignment_mutation_alert_decision_log(evaluated_at); create index if not exists ils_mutation_alert_decision_log_code_idx on public.ils_professional_assignment_mutation_alert_decision_log(failure_code,evaluated_at); create or replace function public.ils_professional_assignment_evaluate_mutation_alerts(p_window_minutes integer default 15) returns integer language plpgsql security definer set search_path=public as $$ declare r record; v_count integer:=0; begin if p_window_minutes is null or p_window_minutes <= 0 then return 0; end if; for r in select a.failure_code,a.window_minutes,a.review_threshold,a.stop_threshold,x.observed_count,x.decision,x.threshold_type from public.ils_professional_assignment_mutation_alert_thresholds a join public.ils_professional_assignment_mutation_telemetry_aggregate(p_window_minutes) x on x.failure_code=a.failure_code and x.observed_count >= a.review_threshold where a.active=true and a.window_minutes=p_window_minutes loop insert into public.ils_professional_assignment_mutation_alert_decision_log(failure_code,window_minutes,observed_count,review_threshold,stop_threshold,decision,threshold_type) values(r.failure_code,r.window_minutes,r.review_threshold,r.stop_threshold,r.decision,r.threshold_type); v_count:=v_count+1; end loop; return v_count; end; $$; revoke all on function public.ils_professional_assignment_evaluate_mutation_alerts(integer) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_evaluate_mutation_alerts(integer) to service_role; create table if not exists public.ils_professional_assignment_alert_evaluation_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_alert_evaluation_tests enable row level security; alter table public.ils_professional_assignment_alert_evaluation_tests force row level security; revoke all on public.ils_professional_assignment_alert_evaluation_tests from anon,authenticated; insert into public.ils_professional_assignment_alert_evaluation_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('NO_ALERTS','NO_LOG','NO_LOG',true,'Below-review conditions create no alert decision records.'),('REVIEW_LOG','LOG_REVIEW','LOG_REVIEW',true,'Review threshold crossing is persisted with thresholds and count.'),('STOP_LOG','LOG_STOP','LOG_STOP',true,'Stop threshold crossing is persisted as STOP.'),('DECISION_TRACE','REQUIRED_FIELDS','REQUIRED_FIELDS',true,'Decision log stores code, window, count, thresholds, decision and threshold type.'),('BACKEND_ONLY_EXECUTION','SERVICE_ROLE_ONLY','SERVICE_ROLE_ONLY',true,'Evaluation function execution is restricted to service_role.'),('CLIENT_EXECUTION','BLOCK','BLOCK',true,'Authenticated and anonymous roles cannot execute evaluator.'),('INVALID_WINDOW','NO_OP','NO_OP',true,'Null/non-positive window produces no evaluation.'),('EMPTY_TELEMETRY','NO_LOG','NO_LOG',true,'Current TEST telemetry is empty, so no synthetic decision record is generated.'),('REPEATED_CYCLE','TRACEABLE','TRACEABLE',true,'Each qualifying evaluation cycle gets its own timestamped record.'),('LIVE_E2E','PENDING','PENDING',true,'No live authenticated failure event exists in TEST; no fake alert is generated.');